// 1. Get raw input
const items = $input.all();
let rawData = items[0]?.json || {};
let finalResult = {};

try {
  if (rawData.hasOwnProperty('0')) {
    const combinedString = Object.values(rawData).join('');
    finalResult = JSON.parse(combinedString);
  } else if (rawData.body && typeof rawData.body === 'object') {
    finalResult = rawData.body;
  } else if (typeof rawData.body === 'string') {
    finalResult = JSON.parse(rawData.body);
  } else {
    finalResult = rawData;
  }
} catch (e) {
  finalResult = rawData;
  finalResult._error = "Parsing failed: " + e.message;
}

const output = {
  ...finalResult,
  tenant_id: parseInt(finalResult.tenant_id || 1001),
  day_of_week: parseInt(finalResult.day_of_week ?? -1),
  _debug_parsed: true
};

return [{ json: output }];

// Flatten adapter — preserves $('DB: Upsert Customer') named references in Code: Validate
const resp = $input.first().json;
return [{ json: resp.data || resp }];

const inputData = $('Debug: Check Input Data').first().json;
const wb = inputData || {};

console.log('Received for Date Gen:', wb);

const specificDates  = (wb.specific_dates || '').trim();
const frequency      = wb.frequency || 'weekly';
const startDateStr   = wb.start_date || '';
const endDateStr     = wb.end_date || '';
const dayOfWeek      = parseInt(wb.day_of_week ?? '-1');
const ratePerSession = parseFloat(wb.rate_per_session || '0') || 0;
const monthlyRate    = parseFloat(wb.monthly_rate || wb.monthly_fee || '0') || 0;
const billingFreq    = (wb.billing_frequency || 'monthly').toLowerCase();
const paymentTiming  = wb.payment_timing || 'in_advance';
const sessFreq = (wb.frequency || wb.session_frequency || 'weekly').toLowerCase();
const sessionsPerMonth = { weekly: 4, fortnightly: 2, monthly: 1 }[sessFreq] || 4;
const effectiveMonthlyRate = monthlyRate > 0
  ? monthlyRate
  : parseFloat((ratePerSession * sessionsPerMonth).toFixed(2));
const periodAmount = parseFloat(wb.period_amount || '0') ||
                     (billingFreq === 'fortnightly' ? effectiveMonthlyRate / 2 : effectiveMonthlyRate) ||
                     ratePerSession;

if (!startDateStr && !specificDates) {
  return [{ json: { error: "Missing start_date or specific_dates", date_count: 0, dates: "", payment_timing: paymentTiming } }];
}

let dates = [];

if (specificDates) {
  dates = specificDates.split(',').map(d => d.trim()).filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d)).sort();
} else {
  const startDate = new Date(startDateStr + 'T12:00:00');
  const maxDate   = endDateStr ? new Date(endDateStr + 'T12:00:00') : new Date(startDate.getFullYear(), startDate.getMonth() + 3, startDate.getDate());
  const dow       = dayOfWeek >= 0 ? dayOfWeek : startDate.getDay();
  const daysToAdd = (dow - startDate.getDay() + 7) % 7;
  const cursor    = new Date(startDate.getTime() + daysToAdd * 86400000);
  while (cursor <= maxDate && dates.length < 100) {
    dates.push(cursor.getFullYear()+'-'+String(cursor.getMonth()+1).padStart(2,'0')+'-'+String(cursor.getDate()).padStart(2,'0'));
    if (frequency === 'monthly') { cursor.setMonth(cursor.getMonth() + 1); }
    else if (frequency === 'fortnightly') { cursor.setDate(cursor.getDate() + 14); }
    else { cursor.setDate(cursor.getDate() + 7); }
  }
}

let monthlyPeriods, monthlyEnds, monthlyAmounts, monthlySessions,
    firstPeriodStart, firstPeriodEnd, firstMonthSessions, firstMonthAmount;

if (paymentTiming === 'per_session') {
  monthlyPeriods  = dates.slice();
  monthlyEnds     = dates.slice();
  monthlyAmounts  = dates.map(() => ratePerSession.toFixed(2));
  monthlySessions = dates.map(() => 1);
  firstPeriodStart   = dates[0] || '';
  firstPeriodEnd     = dates[0] || '';
  firstMonthSessions = dates.length > 0 ? 1 : 0;
  firstMonthAmount   = ratePerSession.toFixed(2);

} else if (billingFreq === 'fortnightly') {
  const anchor = new Date(dates[0] + 'T12:00:00');
  const periodMap = {};
  for (const d of dates) {
    const dt = new Date(d + 'T12:00:00');
    const diffDays = Math.round((dt - anchor) / 86400000);
    const winIdx   = Math.floor(diffDays / 14);
    const winStart = new Date(anchor.getTime() + winIdx * 14 * 86400000);
    const winEnd   = new Date(winStart.getTime() + 13 * 86400000);
    const ks = winStart.getFullYear()+'-'+String(winStart.getMonth()+1).padStart(2,'0')+'-'+String(winStart.getDate()).padStart(2,'0');
    const ke = winEnd.getFullYear()  +'-'+String(winEnd.getMonth()+1  ).padStart(2,'0')+'-'+String(winEnd.getDate()  ).padStart(2,'0');
    if (!periodMap[ks]) periodMap[ks] = { count: 0, period_start: ks, period_end: ke };
    periodMap[ks].count++;
  }
  const sortedKeys = Object.keys(periodMap).sort();
  monthlyPeriods  = sortedKeys.map(k => periodMap[k].period_start);
  monthlyEnds     = sortedKeys.map(k => periodMap[k].period_end);
  monthlyAmounts  = sortedKeys.map(() => periodAmount.toFixed(2));
  monthlySessions = sortedKeys.map(k => periodMap[k].count);
  const fk = sortedKeys[0];
  const fp = fk ? periodMap[fk] : null;
  firstPeriodStart   = fp ? fp.period_start : '';
  firstPeriodEnd     = fp ? fp.period_end   : '';
  firstMonthSessions = fp ? fp.count : 0;
  firstMonthAmount   = periodAmount.toFixed(2);

} else {
  const monthMap = {};
  for (const d of dates) {
    const dt = new Date(d + 'T12:00:00');
    const y  = dt.getFullYear();
    const m  = dt.getMonth();
    const key = y + '-' + String(m + 1).padStart(2, '0');
    if (!monthMap[key]) {
      const mEnd = new Date(y, m + 1, 0);
      monthMap[key] = {
        count: 0,
        period_start: key + '-01',
        period_end:   key + '-' + String(mEnd.getDate()).padStart(2, '0')
      };
    }
    monthMap[key].count++;
  }
  const sortedKeys = Object.keys(monthMap).sort();
  monthlyPeriods  = sortedKeys.map(k => monthMap[k].period_start);
  monthlyEnds     = sortedKeys.map(k => monthMap[k].period_end);
  monthlyAmounts  = sortedKeys.map(() => periodAmount.toFixed(2));
  monthlySessions = sortedKeys.map(k => monthMap[k].count);
  const fk = sortedKeys[0];
  const fm = fk ? monthMap[fk] : null;
  firstPeriodStart   = fm ? fm.period_start : '';
  firstPeriodEnd     = fm ? fm.period_end   : '';
  firstMonthSessions = fm ? fm.count : 0;
  firstMonthAmount   = periodAmount.toFixed(2);
}

return [{ json: {
  dates: dates.join(','),
  date_count: dates.length,
  payment_timing: paymentTiming,
  billing_frequency: billingFreq,
  monthly_rate: monthlyRate.toFixed(2),
  period_amount: periodAmount.toFixed(2),
  monthly_periods_csv:  monthlyPeriods.join(','),
  monthly_ends_csv:     monthlyEnds.join(','),
  monthly_amounts_csv:  monthlyAmounts.join(','),
  monthly_sessions_csv: monthlySessions.join(','),
  monthly_count:  monthlyPeriods.length,
  period_start:   firstPeriodStart,
  period_end:     firstPeriodEnd,
  first_month_sessions: firstMonthSessions,
  first_month_amount:   firstMonthAmount
} }];

const wb = $('Debug: Check Input Data').first().json;
const customerRow = $('DB: Upsert Customer').first().json;
const dateGen = $('Code: Generate Dates').first().json;

const customer_id = customerRow?.customer_id;
const room_id = wb?.room_id;
const tenant_id = wb?.tenant_id;

console.log("Validation Check:", { customer_id, room_id, tenant_id, date_count: dateGen.date_count });

if (!customer_id) {
  throw new Error("Validation Error: The database did not return a customer_id. Check 'DB: Upsert Customer' output.");
}

if (!room_id || !tenant_id) {
  throw new Error(`Validation Error: Missing Webhook data. Room: ${room_id}, Tenant: ${tenant_id}`);
}

if (!dateGen.dates || dateGen.date_count === 0) {
  throw new Error("Validation Error: No dates were generated for this booking.");
}

return [{
  json: {
    customer_id,
    room_id,
    tenant_id,
    dates: dateGen.dates,
    date_count: dateGen.date_count,
    first_month_amount: dateGen.first_month_amount,
    customer_name: customerRow.full_name || wb.customer_name,
    customer_email: customerRow.email || wb.customer_email
  }
}];

// Flatten adapter — Code: Filter Dates reads $input.first().json.clashed_dates
const resp = $input.first().json;
const data = resp.data || resp;
return [{ json: { clashed_dates: data.clashed_dates || [] } }];

const validate = $('Code: Validate').first().json;
const allDates = (validate.dates || '').split(',').filter(Boolean).sort();
const clashRow = $input.first().json;
const clashed = new Set((clashRow.clashed_dates || []).map(d => String(d).trim().slice(0,10)));

if (clashed.size === 0) {
  return [{ json: {
    filtered_dates: validate.dates || '',
    dates_count: allDates.length,
    has_conflict: false,
    blocked: false,
    warning: null
  }}];
}

const sortedClashed = [...clashed].sort();
const firstConflict = sortedClashed[0];
const safeDates = allDates.filter(d => d < firstConflict);

const fmtDate = d => {
  const dt = new Date(d + 'T12:00:00');
  return dt.toLocaleDateString('en-GB', {day:'numeric', month:'long', year:'numeric'});
};

if (safeDates.length === 0) {
  return [{ json: {
    filtered_dates: '',
    dates_count: 0,
    has_conflict: true,
    blocked: true,
    first_conflict_date: firstConflict,
    warning: 'The first session date (' + fmtDate(firstConflict) + ') is already booked for this room at this time. Please choose a different start date or room.'
  }}];
}

return [{ json: {
  filtered_dates: safeDates.join(','),
  dates_count: safeDates.length,
  has_conflict: true,
  blocked: false,
  first_conflict_date: firstConflict,
  clashed_count: clashed.size,
  warning: 'Recurring series created for ' + safeDates.length + ' session(s) up to ' + fmtDate(safeDates[safeDates.length-1]) + '. Bookings stop before ' + fmtDate(firstConflict) + ' — that date is already taken by an existing booking.'
}}];

